document.querySelectorAll("[data-faq-accordion]").forEach((function(list){list.querySelectorAll("[data-faq-toggle]").forEach((function(button){button.addEventListener("click",(function(){const item=button.closest(".strip-faq__item"),answer=document.getElementById(button.getAttribute("aria-controls")),isOpen="true"===button.getAttribute("aria-expanded");list.querySelectorAll("[data-faq-toggle]").forEach((function(otherButton){otherButton!==button&&(otherButton.setAttribute("aria-expanded","false"),otherButton.closest(".strip-faq__item").classList.remove("is-open"),document.getElementById(otherButton.getAttribute("aria-controls")).hidden=!0)})),button.setAttribute("aria-expanded",isOpen?"false":"true"),item.classList.toggle("is-open",!isOpen),answer.hidden=isOpen}))}))}));